/* ---------- calculations ---------- */
const axItem=id=>(D.ax.items||[]).find(i=>i.id===id);
const axParty=id=>(D.ax.parties||[]).find(p=>p.id===id)||{n:id||'—',state:'',gstin:''};
const axInter=t=>{const p=axParty(t.party);return !!(p.state&&p.state!==AXST[t.co])};
function axLine(l){const i=l.it?axItem(l.it):null;return {n:l.n||(i&&i.n)||'Item',hsn:l.hsn||(i&&i.hsn)||'',gst:l.gst!=null?+l.gst:(i?i.gst:0),qty:+l.qty||0,rate:+l.rate||0,unit:(i&&i.unit)||'',disc:+l.disc||0}}
function axCalc(t){if(['pin','pout','prod'].includes(t.ty)){const a=+t.amt||0;return {sub:a,tax:0,cg:0,sg:0,ig:0,tot:a,lines:[]}}
 const inter=axInter(t);let sub=0,tax=0;const L=(t.lines||[]).map(l=>{const x=axLine(l),amt=axR(x.qty*x.rate*(1-x.disc/100)),tx=axR(amt*x.gst/100);sub+=amt;tax+=tx;return Object.assign(x,{amt,tx})});
 const tot=Math.round(sub+tax);return {sub:axR(sub),tax:axR(tax),cg:inter?0:axR(tax/2),sg:inter?0:axR(tax/2),ig:inter?axR(tax):0,tot,round:axR(tot-sub-tax),lines:L,inter}}
const axBal=t=>t.ty==='sale'?Math.max(0,axCalc(t).tot-(t.rcv||0)):['purchase','expense'].includes(t.ty)?Math.max(0,axCalc(t).tot-(t.pd||0)):0;
const axStatus=t=>{if(!['sale','purchase','expense'].includes(t.ty))return ['Done','#16A34A'];const b=axBal(t),tot=axCalc(t).tot;if(b<=0.5)return ['Paid','#16A34A'];if(t.due&&t.due<TODAY)return ['Overdue','#EA580C'];return b<tot?['Partial','#2563EB']:['Unpaid','#DC2626']};
function axPer(){const p=S.axp||'m',d=new Date(TODAY+'T12:00:00'),y=d.getFullYear(),m=d.getMonth(),iso=x=>x.toISOString().slice(0,10),fy=m<3?y-1:y;
 if(p==='m')return [iso(new Date(y,m,1,12)),iso(new Date(y,m+1,0,12)),'This month'];if(p==='lm')return [iso(new Date(y,m-1,1,12)),iso(new Date(y,m,0,12)),'Last month'];
 if(p==='q'){const q=Math.floor(((m+9)%12)/3),qs=new Date(fy,3+q*3,1,12);return [iso(qs),iso(new Date(fy,6+q*3,0,12)),'This quarter']}
 if(p==='fy')return [fy+'-04-01',(fy+1)+'-03-31','FY '+fy+'-'+String(fy+1).slice(2)];if(p==='c')return [S.axa||TODAY,S.axb||TODAY,'Custom'];return ['2000-01-01','2999-12-31','All time']}
