const axCostOf=id=>{const i=axItem(id);if(!i)return 0;if(i.buy)return i.buy;const b=D.ax.bom[id];return b?b.reduce((a,[c,n])=>a+n*axCostOf(c),0):0};
function axAcctBal(a,upto){let b=a.open||0;(D.ax.txns||[]).forEach(t=>{if(upto&&t.dt>upto)return;if(t.ty==='sale'&&t.acct===a.id)b+=+t.rcv0||0;if(t.ty==='pin'&&t.acct===a.id)b+=+t.amt;if(['purchase','expense'].includes(t.ty)&&t.acct===a.id)b-=+t.pd0||0;if(t.ty==='pout'&&t.acct===a.id)b-=+t.amt;if(t.ty==='journal'&&t.to===a.id)b+=+t.amt;if(t.ty==='journal'&&t.from===a.id)b-=+t.amt});return b}
function axPartyBal(pid){let b=0;(D.ax.txns||[]).forEach(t=>{if(t.party!==pid)return;if(t.ty==='sale')b+=axBal(t);if(t.ty==='sret')b-=axCalc(t).tot;if(['purchase'].includes(t.ty))b-=axBal(t);if(t.ty==='pret')b+=axCalc(t).tot});return b}
function axPL(co,a,b){const ok=t=>(!co||t.co===co)&&t.dt>=a&&t.dt<=b,T=D.ax.txns.filter(ok),sum=(ty,k)=>T.filter(t=>t.ty===ty).reduce((x,t)=>x+axCalc(t)[k||'sub'],0);const stv=d=>D.ax.items.filter(i=>i.track&&(!co||i.co===co)).reduce((x,i)=>x+axStock(i.id,d)*axCostOf(i.id),0);const sal=sum('sale')-sum('sret'),pur=sum('purchase')-sum('pret'),exp=sum('expense'),cogs=stv(axAdd(a,-1))+pur-stv(b>TODAY?TODAY:b);return {sal,pur,exp,cogs,np:sal-cogs-exp}}
