const AXV={};
AXV.home=()=>{const S_=axT('sale'),Pu=axT('purchase'),E=axT('expense');const sal=S_.reduce((a,t)=>a+axCalc(t).sub,0),pur=Pu.reduce((a,t)=>a+axCalc(t).sub,0),exp=E.reduce((a,t)=>a+axCalc(t).sub,0);
 const all=D.ax.txns.filter(axCoOk),rec=all.filter(t=>t.ty==='sale').reduce((a,t)=>a+axBal(t),0),pay=all.filter(t=>t.ty==='purchase').reduce((a,t)=>a+axBal(t),0);
 const cash=D.ax.accts.filter(axCoOk).reduce((a,x)=>a+axAcctBal(x),0),out=S_.reduce((a,t)=>a+axCalc(t).tax,0),inp=[...Pu,...E].reduce((a,t)=>a+axCalc(t).tax,0);
 const [pa,pb]=axPer();const prof=axPL(S.axc,pa,pb).np;
 /* last month comparison */
 const months=[];for(let i=5;i>=0;i--){const d=new Date(TODAY+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()-i);const k=d.toISOString().slice(0,7);const T=D.ax.txns.filter(t=>axCoOk(t)&&t.dt.slice(0,7)===k);months.push([d.toLocaleDateString('en-IN',{month:'short'}),T.filter(t=>t.ty==='sale').reduce((a,t)=>a+axCalc(t).sub,0),T.filter(t=>['purchase','expense'].includes(t.ty)).reduce((a,t)=>a+axCalc(t).sub,0)])}
 const mx=Math.max(1,...months.flatMap(m=>[m[1],m[2]]));
 const top=(()=>{const M={};S_.forEach(t=>{M[t.party]=(M[t.party]||0)+axCalc(t).tot});return Object.entries(M).sort((a,b)=>b[1]-a[1]).slice(0,5)})();
 const due=D.ax.txns.filter(t=>axCoOk(t)&&t.ty==='sale'&&axStatus(t)[0]==='Overdue').sort((a,b)=>a.due.localeCompare(b.due)).slice(0,6);
 const cl=axClaims().filter(v=>!v.axPaid);
 return `${axPage('Business at a glance',`${axCoN(S.axc)} · ${axPer()[2]}`)}
 <div class="axkp">${axKpi('Sales (before GST)',axI(sal),S_.length+' invoices','#DC2626',`data-a="axGo" data-v="sale"`)}${axKpi('Purchases',axI(pur),Pu.length+' bills','#2563EB',`data-a="axGo" data-v="purchase"`)}${axKpi('Expenses',axI(exp),E.length+' entries','#7C3AED',`data-a="axGo" data-v="expense"`)}${axKpi('Net profit',axI(prof),sal?Math.round(prof/sal*100)+'% margin · see P&L':'','#16A34A',`data-a="axRep" data-r="pl"`)}
 ${axKpi('To collect',axI(rec),'all open sale bills','#EA580C',`data-a="axRep" data-r="aging"`)}${axKpi('To pay',axI(pay),'all open purchase bills','#B45309',`data-a="axRep" data-r="parties"`)}${axKpi('Cash + bank',axI(cash),D.ax.accts.filter(axCoOk).length+' accounts','#0F766E',`data-a="axGo" data-v="bank"`)}${axKpi('GST payable',axI(Math.max(0,out-inp)),`output ${axI(out)} − input ${axI(inp)}`,'#0E7490',`data-a="axRep" data-r="gstr3b"`)}</div>
 <div class="axg2"><div class="axcard"><div class="axth"><b>Sales vs purchases + expenses · last 6 months</b></div><div class="axch">${months.map(([m,a,b])=>`<div><div class="axcb"><i style="height:${a/mx*100}%;background:#DC2626" title="Sales ${axI(a)}"></i><i style="height:${b/mx*100}%;background:#93C5FD" title="Costs ${axI(b)}"></i></div><b class="${a-b<0?'neg':''}">${axI(a-b)}</b><span>${m}</span></div>`).join('')}</div><div class="axlg"><i style="background:#DC2626"></i>Sales <i style="background:#93C5FD"></i>Purchases + expenses · number = profit</div></div>
 <div class="axcard"><div class="axth"><b>${S.axc?'Top customers':'Company-wise'}</b></div>${S.axc?top.map(([p,a])=>`<div class="axrw"><span>${h(axParty(p).n)}</span><b>${axI(a)}</b></div>`).join('')||'<div class="axempty">No sales yet</div>':AXCO.map(k=>{const L=axPL(k,pa,pb);return `<button class="axrw axcow" data-a="axCo" data-k="${k}" style="--cc:${axCoC(k)}"><span><i></i>${h(axCoN(k))}</span><small>sales ${axI(L.sal)} · profit</small><b class="${L.np<0?'neg':'pos'}">${axI(L.np)}</b></button>`}).join('')}</div></div>
 <div class="axg2"><div class="axcard"><div class="axth"><b>Overdue bills · follow up</b><span class="sp"></span><button class="axlnk" data-a="axRep" data-r="aging">Sale aging ›</button></div>${due.map(t=>`<button class="axrw" data-a="axOpen" data-id="${t.id}"><span>${h(axParty(t.party).n)}<small>${h(t.no)} · due ${axD(t.due)}</small></span><b class="neg">${axI(axBal(t))}</b></button>`).join('')||'<div class="axempty">Nothing overdue 🎉</div>'}</div>
 <div class="axcard"><div class="axth"><b>Staff claims waiting</b><span class="sp"></span><button class="axlnk" data-a="axGo" data-v="claims">All claims ›</button></div>${cl.slice(0,6).map(v=>`<div class="axrw"><span>${h(nmF(v.by))} · ${h(v.head||v.party||'Expense')}<small>${h(coShort(v.co))} · ${axD(v.dt)} · ${axClaimSt(v)[0]}</small></span><b>${axI(v.amt)}</b></div>`).join('')||'<div class="axempty">No claims waiting</div>'}</div></div>`};
const axTxnView=(ty,title,sub)=>()=>axPage(title,sub,`<button class="${ty==='sale'||ty==='sret'||ty==='pin'?'axbs':'axbp'}" data-a="axNew" data-t="${ty}">${ic('plus')}${({sale:'Add Sale',purchase:'Add Purchase',expense:'Add Expense',pin:'Payment In',pout:'Payment Out',sret:'Sale Return',pret:'Purchase Return'})[ty]}</button>`)+axTxnTable(axList(ty),ty);
AXV.sale=axTxnView('sale','Sale invoices','GST invoices · CGST + SGST inside the state, IGST outside');
AXV.purchase=axTxnView('purchase','Purchase bills','Bills from suppliers · input GST (ITC) is claimed from these');
